it('throws at registration time for an uncompilable schema naming the tool', () => {
  const registry = new ToolRegistry();

  expect(() =>
    registry.register(
      {
        name: 'broken_tool',
        description: 'Has an uncompilable schema',
        inputSchema: {
          type: 'object',
          properties: {field: {type: 'not-a-valid-type'}},
        },
      },
      async () => 'unreachable'
    )
  ).toThrow(/broken_tool/);
