it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
  const reg = new ToolRegistry();
  let invocations = 0;
  reg.register(
    {
      name: 'fetch_weather',
      description: 'Fetch weather report',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    async () => {
      invocations += 1;
      return 'cloudy';
    }
  );

  const reply = await reg.execute('fetch_weather', {});

  expect(invocations).toBe(0);
  expect(reply.result).toContain('location');
  expect(reply.result).toMatch(/required/i);
});

it('rejects a wrong-typed property naming the field and expected type without leaking the offending value', async () => {
  const reg = new ToolRegistry();
  let runCount = 0;
  reg.register(
    {
      name: 'validate_age',
      description: 'Check age value',
      inputSchema: {
        type: 'object',
        properties: {age: {type: 'number'}},
        required: ['age'],
      },
    },
    async () => {
      runCount += 1;
      return 'valid';
    }
  );

  const secretWrongVal = 'NOT_A_NUMBER_SECRET';
  const response = await reg.execute('validate_age', {age: secretWrongVal});

  expect(runCount).toBe(0);
  expect(response.result).toContain('age');
  expect(response.result).toContain('number');
  expect(response.result).not.toContain(secretWrongVal);
});

