it('throws at registration time for an uncompilable schema naming the tool', () => {
  const registry = new ToolRegistry();
  const badTool = {
    description: 'Has an uncompilable schema',
    inputSchema: {
      properties: {field: {type: 'not-a-valid-type'}},
      type: 'object',
    },
    name: 'broken_tool',
  };
  expect(() => registry.register(badTool, jest.fn())).toThrow(/broken_tool/);
});

it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
  const registry = new ToolRegistry();
  const mockExecutor = jest.fn();
  const weatherSchema = {
    properties: {location: {type: 'string'}},
    required: ['location'],
    type: 'object' as const,
  };
  registry.register(
    {description: 'Fetch weather report', inputSchema: weatherSchema, name: 'fetch_weather'},
    mockExecutor
  );

  const reply = await registry.execute('fetch_weather', {});

  expect(mockExecutor).not.toHaveBeenCalled();
  expect(reply.result).toContain('location');
  expect(reply.result).toMatch(/required/i);
});

it('rejects a wrong-typed property naming the field and expected type without leaking the offending value', async () => {
  const registry = new ToolRegistry();
  const mockExecutor = jest.fn();
  const ageSchema = {
    properties: {age: {type: 'number'}},
    required: ['age'],
    type: 'object' as const,
  };
  registry.register({description: 'Check age value', inputSchema: ageSchema, name: 'validate_age'}, mockExecutor);

  const secretWrongVal = 'NOT_A_NUMBER_SECRET';
  const response = await registry.execute('validate_age', {age: secretWrongVal});

  expect(mockExecutor).not.toHaveBeenCalled();
  expect(response.result).toContain('age');
  expect(response.result).toContain('number');
  expect(response.result).not.toContain(secretWrongVal);
});

